import hashlib
import os

def get_file_hash(filepath):
    hasher = hashlib.sha256()
    try:
        with open(filepath, 'rb') as f:
            while chunk := f.read(8192):
                hasher.update(chunk)
        return hasher.hexdigest()
    except Exception:
        return None

def find_duplicates(root_dir):
    hashes = {}
    for root, dirs, files in os.walk(root_dir):
        for filename in files:
            filepath = os.path.join(root, filename)
            file_hash = get_file_hash(filepath)
            if file_hash is not None:
                # Get relative path with forward slashes
                rel_path = os.path.relpath(filepath, root_dir).replace(os.sep, '/')
                if file_hash in hashes:
                    hashes[file_hash].append(rel_path)
                else:
                    hashes[file_hash] = [rel_path]

    duplicates = []
    for file_list in hashes.values():
        if len(file_list) > 1:
            # Sort files within the group alphabetically
            file_list.sort()
            duplicates.append(file_list)

    # Sort groups by their first file's path
    duplicates.sort(key=lambda x: x[0])
    return duplicates

root = 'dosyalar'
if os.path.exists(root):
    dupes = find_duplicates(root)
    with open('kopyalar.txt', 'w', encoding='utf-8') as f:
        for group in dupes:
            f.write(" | ".join(group) + "\n")
    print(f"Found {len(dupes)} duplicate groups.")
else:
    print("Directory 'dosyalar' not found.")

